import{readFileSync,writeFileSync,existsSync,unlinkSync}from'node:fs';import{spawnSync}from'node:child_process';import{homedir}from'node:os';import{join}from'node:path';import{productionEnvironment,productionPsql}from'../scripts/lib/production-database.mjs';
const out='.verification/capacity-two-control-cleanup-receipt-20261024.json';if(existsSync(out))throw Error('CONTROL_CLEANUP_RECEIPT_EXISTS');const a=JSON.parse(readFileSync('.verification/capacity-two-control-analysis-v2-20261024.json'));if(a.comparisonRun!==40099997857||!a.integrity.rowsSafe||!a.thresholdsRecomputedAndMatched)throw Error('CONTROL_INTEGRITY_NOT_APPROVED_INSPECT_BEFORE_CLEANUP');const r={at:new Date().toISOString(),run:40099997857,status:'cleanup-starting',scope:'Only deterministic synthetic capacity practices/owners from the completed comparison. HTTP acceptance may fail, but own-row isolation/overlap checks and supported SQL ownership guards must pass before cleanup. Unknown cumulative counters are not represented as passed. Remove temporary Actions/local secret only after guarded cleanup succeeds.'};const save=()=>writeFileSync(out,JSON.stringify(r,null,2)+'\n',{mode:0o600});save();
const q=spawnSync('node',['--max-old-space-size=192','scripts/production-capacity.mjs','cleanup'],{encoding:'utf8',timeout:180000,maxBuffer:2**22});writeFileSync('.verification/capacity-two-control-cleanup-20261024.log',(q.stdout??'')+(q.stderr??''),{flag:'wx',mode:0o600});if(q.status||q.error)throw Error('SUPPORTED_CAPACITY_CLEANUP_FAILED');const line=q.stdout.split('\n').find(x=>x.startsWith('production-capacity-cleanup '));if(!line)throw Error('CLEANUP_RESULT_MISSING');const d=JSON.parse(line.slice('production-capacity-cleanup '.length));if(d.practices!==2||d.patients<12000||d.appointments<24000||d.ownersRemoved!==2||d.remaining.practices||d.remaining.owners)throw Error('CLEANUP_RESULT_NOT_EXACT');r.removed=d;r.status='owned-rows-cleaned';save();
const{database}=productionEnvironment(process.cwd());const state=JSON.parse(productionPsql(database,"begin transaction read only;select json_build_object('businesses',(select count(*)from public.businesses),'patients',(select count(*)from public.patients),'appointments',(select count(*)from public.appointments),'calendarConnections',(select count(*)from public.google_calendar_connections),'calendarEvents',(select count(*)from public.appointment_google_calendar_events),'storedObjects',(select count(*)from storage.objects),'storedObjectBytes',(select sum((metadata->>'size')::bigint)from storage.objects),'migrations',(select count(*)from supabase_migrations.schema_migrations),'legacyEnabled',public.legacy_job_entrypoints_enabled());commit;",{application:'cita_suite_control_cleanup_readback'}).trim());const before=JSON.parse(readFileSync('.verification/production-final-readonly-state-20261024.json'));for(const key of['businesses','patients','appointments','calendarConnections','calendarEvents','storedObjects','storedObjectBytes','migrations','legacyEnabled'])if(state[key]!==before[key])throw Error('PREEXISTING_STATE_COUNTS_CHANGED_INSPECT');r.preexistingCountsRestored=state;save();
const repo='Juan4787/cita-suite-verificacion';let g=spawnSync('gh',['secret','delete','CITA_PRODUCTION_CAPACITY_SECRET','--repo',repo],{encoding:'utf8',timeout:35000});if(g.status)throw Error('TEMPORARY_ACTIONS_SECRET_DELETE_FAILED');g=spawnSync('gh',['secret','list','--repo',repo,'--json','name'],{encoding:'utf8',timeout:35000});if(g.status||JSON.parse(g.stdout).some(x=>x.name==='CITA_PRODUCTION_CAPACITY_SECRET'))throw Error('TEMPORARY_ACTIONS_SECRET_REMAINS');unlinkSync(join(homedir(),'.config/cita-suite/production/capacity-secret'));r.temporaryActionsSecretRemoved=true;r.temporaryLocalSecretRemoved=true;r.applicationCredentialsChanged=false;r.passed=true;r.status='guarded-comparison-cleanup-and-temporary-secret-removal-complete';r.finishedAt=new Date().toISOString();save();console.log({status:r.status,passed:r.passed,practicesRemoved:d.practices,ownersRemoved:d.ownersRemoved,preexistingCountsRestored:true});
